export interface GalleryImage {
  /** Full-quality image (Astro asset URL). */
  src: string;
  /** Small webp generated by vite-imagetools, used for the thumbnail strip. */
  thumb: string;
}

export interface GallerySection {
  name: string;
  images: GalleryImage[];
}

const full = import.meta.glob<{ default: ImageMetadata }>(
  "/src/assets/gallery/**/*.{png,jpg,jpeg,webp,gif,avif}",
  { eager: true },
);

// 160px wide = 2x for the 80px thumbnails, so they stay crisp on hi-dpi screens.
const thumbs = import.meta.glob<string>(
  "/src/assets/gallery/**/*.{png,jpg,jpeg,webp,gif,avif}",
  {
    eager: true,
    import: "default",
    query: { w: "100", format: "webp" },
  },
);

export async function loadGallery(): Promise<GallerySection[]> {
  const sections: Record<string, GallerySection> = {};

  for (const [path, mod] of Object.entries(full)) {
    const parts = path.split("/");
    const sectionName = parts[parts.length - 2];

    sections[sectionName] ??= { name: sectionName, images: [] };
    sections[sectionName].images.push({
      src: mod.default.src,
      thumb: thumbs[path] ?? mod.default.src,
    });
  }

  return Object.values(sections);
}